import type OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';

import { focusManager } from '../services/focus-manager';

const logger = createLogger('common.addressBarFocus');
import { FOCUS_PRIORITY } from '../types/focus';

import { isLandingPageOrEmpty } from './enterpriseBrowser';

/**
 * Handles address bar focus logic for landing pages.
 *
 * This function enables the following behaviors:
 * - When a new view tab is created via the new tab button that is on the landing page, the address input will focus.
 * - When a user clicks on an inactive view tab on the landing page, the address input will focus.
 * - When a user clicks on an active view tab on the landing page while the address input bar is focused, the view will focus.
 *
 * @param viewIdentity - The view identity to check
 * @param isModalOpen - Function that returns whether a modal is currently open
 * @returns Promise<boolean> - Returns true if address bar was focused, false otherwise
 */
export const handleAddressBarFocusForLandingPage = async (
    viewIdentity: OpenFin.Identity,
    isModalOpen: () => boolean = () => false
): Promise<boolean> => {
    // Don't focus if modal is open
    if (isModalOpen()) {
        return false;
    }

    try {
        const { url } = await fin.View.wrapSync(viewIdentity).getInfo();

        if (isLandingPageOrEmpty(url)) {
            // Request focus on address bar via focus manager
            focusManager.requestFocus({
                target: { type: 'addressBar' },
                priority: FOCUS_PRIORITY.ADDRESS_BAR,
                source: 'programmatic'
            });
            return true;
        }
    } catch (error) {
        logger.error('handleAddressBarFocusForLandingPage', 'Error checking view URL', {
            error: error instanceof Error ? error.message : String(error)
        });
    }

    return false;
};

/**
 * Gets the address bar input element
 */
export const getAddressBarInputElement = (): HTMLInputElement | null => {
    return document.getElementById('address-bar-url-input') as HTMLInputElement;
};

/**
 * Blur the address bar input to prevent focus inconsistencies
 * when a view is focused.
 */
export const blurAddressBar = (): void => {
    const addressBar = getAddressBarInputElement();
    if (addressBar) {
        addressBar.blur();
    }
};
