import type OpenFin from '@openfin/core';

/**
 * Safely resolves the currently focused OpenFin content identity.
 * Returns null when focus is outside runtime content or unavailable.
 */
export const getFocusedContents = async (): Promise<OpenFin.Identity | null> => {
    try {
        return await fin.System.getFocusedContent();
    } catch {
        return null;
    }
};
