import { Flag, flag } from '@common/api/flags';
import { createLogger } from '@common/utils/logger';

const logger = createLogger('common.debugLog');

const isWorkspaceDebugEnabled = (): boolean => flag(Flag.DevDebug);

export const createInlineDebugLogger = (
    namespace: string
): ((event: string, data?: Record<string, unknown>) => void) => {
    return (event: string, data?: Record<string, unknown>) => {
        if (!isWorkspaceDebugEnabled()) {
            return;
        }

        logger.debug('inline', event, {
            namespace,
            timestamp: Date.now(),
            ...(data ?? {})
        });
    };
};
